head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF37306.xml";
scwin.designTpCd;
scwin.gLdMktTp = js_market;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//부모창에서 필요변수 저장
scwin.fn_GetParentValue = function() {
    scwin.designTpCd = frame.opener.scwin.designTpCd;
};
scwin.fn_Search = function() {
    var vCOM_NM = $c.stf.getObjectValue(txb_Search);
    var url = "/ByPass.do?method=listDesignExcludeCompany";
    url += "&COM_NM=" + vCOM_NM;
    url += "&DESIGN_EXCLUDE_TP_CD=" + scwin.designTpCd; //지정:1, 해제:2
    url += "&LD_MKT_TP_CD=" + scwin.gLdMktTp; // 시장구분
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    $c.cm.ShowWin(grd_Grid);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    $c.frame.path("../").txb_isur_cd.setValue(dts_List.getCellData(row, "ISUR_CD")); //부모창 회사코드
    $c.frame.path("../").txb_com_nm.setValue(dts_List.getCellData(row, "COM_ABBRV")); //부모창 회사명
    $c.frame.path("../").txb_dtec_dd.setValue(dts_List.getCellData(row, "DTEC_DD")); //부모창 적출일자
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.txb_Search_onkeypress = function() {
    if (window.event.keyCode == 13) {
        scwin.fn_Search();
    }
};
scwin.gform_onload = function() {
    scwin.fn_GetParentValue();
    scwin.fn_Search();
};
